import {rbCases} from './redblack-lab-content.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function rbTreeSVG(root,{roles={},debt=null,showNil=false,title='红黑树'}={}){
 const reverse={};for(const [r,id]of Object.entries(roles))(reverse[id]??=[]).push(r);
 const points=[],edges=[];let i=0,depthMax=0;
 function walk(n,d=0){const a=n.nil?null:walk(n.left,d+1),p={n,x:50+45*i++,y:48+100*d};const visible=!n.nil||showNil||n.id===debt||reverse[n.id];if(visible)points.push(p);const b=n.nil?null:walk(n.right,d+1);if(a)edges.push([p,a]);if(b)edges.push([p,b]);depthMax=Math.max(d,depthMax);return visible?p:null}walk(root);
 const width=Math.max(330,100+45*Math.max(0,i-1)),height=Math.max(160,145+100*depthMax);
 return `<svg xmlns="http://www.w3.org/2000/svg" class="rb-tree-svg" role="img" aria-label="${esc(title)}" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}"><title>${esc(title)}</title><desc>红节点同时标 R，黑节点标 B；橙色外环 +1 表示 X 处的虚拟额外黑。灰框 NIL 实际为黑。</desc><g font-family="Microsoft YaHei,sans-serif" text-anchor="middle">${edges.map(([a,b])=>`<path d="M${a.x} ${a.y} L${b.x} ${b.y}" stroke="${b.n.color==='R'?'#bd625c':'#9ba8aa'}" stroke-width="${b.n.color==='R'?3:1.8}"/>`).join('')}${points.map(({n,x,y})=>`<g data-rb-node="${n.id}" data-x="${x}" data-y="${y}" transform="translate(${x} ${y})">${n.id===debt?'<circle r="32" fill="none" stroke="#c87a17" stroke-width="3" stroke-dasharray="6 3"/><rect x="18" y="-37" width="30" height="23" rx="6" fill="#a95c0b"/><text x="33" y="-21" fill="white" font-size="13">+1</text>':''}${n.nil?'<rect x="-24" y="-16" width="48" height="32" rx="5" fill="#e5ebed" stroke="#586c73"/><text y="5" font-size="12" fill="#263e48">NIL · B</text>':`<circle class="rb-node-body" r="24" fill="${n.color==='R'?'#b74640':'#293f49'}" stroke="${reverse[n.id]?'#dca753':'#fff'}" stroke-width="${reverse[n.id]?3:1.5}"/><text y="5" font-size="17" font-weight="600" fill="white">${n.key}</text><text x="19" y="-20" font-size="11" font-weight="bold" stroke="#fafbf8" stroke-width="3" paint-order="stroke" fill="${n.color==='R'?'#a03632':'#293f49'}">${n.color}</text>`}<text y="45" fill="#785716" font-size="13" font-weight="bold">${(reverse[n.id]||[]).join(' / ')}</text><text y="61" fill="#75818a" font-size="10">${n.id}</text></g>`).join('')}${!points.length?'<text x="165" y="80" fill="#697570">∅ 空树，根为黑 NIL</text>':''}</g></svg>`
}
export function rbGuideSVG(active=null){
 const boxes=[['I1',28,235],['I2',28,395],['I3',28,555],['D1',583,235],['D2',583,395],['D3',583,555],['D4',583,715]];
 const short={I1:['叔叔红','父叔黑，祖父红；X 移到 G','不旋转；可能继续向上'],I2:['叔叔黑 + 折线','先转 P，让 X 上升；不变色','形状转换 → 必须接 I3'],I3:['叔叔黑 + 直线','P 黑、G 红；转 G，让 P 上升','冲突消失 → 结束'],D1:['兄弟红','S 黑、P 红；转 P，让 S 上升','先换黑兄；重新判 D2 / D3 / D4'],D2:['兄黑 + 两侄黑','S 染红；X ← P，亏欠上移','遇红吸收，到根终止，否则继续'],D3:['兄黑 + 近红远黑','N 黑、S 红；转 S，让 N 上升','转出远红 → 必须接 D4'],D4:['兄黑 + 远侄红','S 继承 P 原色；P、F 黑；转 P','亏欠消除 → 结束（近侄任意色）']};
 return `<svg xmlns="http://www.w3.org/2000/svg" class="rb-guide-svg" viewBox="0 0 1120 975" width="1120" height="975" role="img" aria-label="红黑树插入删除决策记忆图"><title>红黑树：插入看叔，删除看兄侄</title><rect width="1120" height="975" rx="14" fill="#fafbf8"/><g font-family="Microsoft YaHei,sans-serif"><text x="28" y="44" font-size="27" font-weight="bold" fill="#233c36">先认角色，再判颜色；最后说清谁上升</text><text x="28" y="77" font-size="15" fill="#68796f">普通对称红黑树 · X 在右时全部镜像 · R/B 双重标记，不只靠颜色识别</text><path d="M555 115 V916" stroke="#d8e0d3"/>
 <rect x="28" y="115" width="508" height="97" rx="10" fill="#f5e6e1"/><text x="46" y="148" font-size="23" font-weight="bold" fill="#9b3730">插入：修红红冲突</text><text x="46" y="176" font-size="16" fill="#573e35">先插红叶；父黑就结束，父红再看叔。</text><text x="46" y="198" font-size="13" fill="#785d50">X 当前节点 · P 父 · G 祖父 · U 叔</text>
 <rect x="583" y="115" width="508" height="97" rx="10" fill="#f6eddc"/><text x="601" y="148" font-size="23" font-weight="bold" fill="#936013">删除：修黑色亏欠</text><text x="601" y="176" font-size="15" fill="#665134">摘红即止；红 X 染黑；黑 X 非根才查兄侄。</text><text x="601" y="198" font-size="13" fill="#785d50">X 欠黑位 · P 父 · S 兄 · N 近侄 · F 远侄</text>
 ${boxes.map(([id,x,y])=>`<g data-rb-guide="${id}" role="button" tabindex="0" aria-label="${esc(id+' '+rbCases[id].name+'，打开对应动画')}"><rect x="${x}" y="${y}" width="508" height="137" rx="9" fill="${id===active?'#fff2d6':'#ffffff'}" stroke="${id===active?'#be7b21':'#d2decf'}" stroke-width="${id===active?3:1}"/><text x="${x+17}" y="${y+31}" font-size="18" font-weight="bold" fill="#264c3c">${id} · ${short[id][0]}</text><text x="${x+17}" y="${y+67}" font-size="16" fill="#263e35">${short[id][1]}</text><text x="${x+17}" y="${y+104}" font-size="14" fill="#68786b">${short[id][2]}</text></g>`).join('')}
 <text x="52" y="769" font-size="19" font-weight="bold" fill="#a13e36">叔红推；叔黑先拉直，再换色旋祖。</text><text x="52" y="803" font-size="15" fill="#68786b">I1 可重复，I2 → I3 结束。</text><text x="52" y="835" font-size="15" fill="#68786b">最多 2 次旋转；变色与查找 O(log n)。</text>
 <text x="28" y="903" font-size="18" font-weight="bold" fill="#855b1b">删除口诀：兄红换，双黑推，近红转，远红收。</text><text x="28" y="935" font-size="15" fill="#68786b">只有 D2 可以向上重复；D3 → D4 必结束；最多 D1 → D3 → D4 三次旋转。</text></g></svg>`
}
export function rb234SVG(root){
 function group(b){if(b.nil)return null;const nodes=[],children=[];if(b.left.color==='R'){nodes.push(b.left.key);children.push(group(b.left.left),group(b.left.right))}else children.push(group(b.left));nodes.push(b.key);if(b.right.color==='R'){nodes.push(b.right.key);children.push(group(b.right.left),group(b.right.right))}else children.push(group(b.right));return{keys:nodes,children}}
 const tree=group(root),placed=[],edges=[];let cursor=0,maxY=0;
 function layout(n,d=0){if(!n)return null;const kids=n.children.map(c=>layout(c,d+1)).filter(Boolean),p={n,x:kids.length?kids.reduce((a,c)=>a+c.x,0)/kids.length:75+160*cursor++,y:40+105*d};placed.push(p);kids.forEach(k=>edges.push([p,k]));maxY=Math.max(maxY,p.y);return p}layout(tree);const width=Math.max(330,150+160*Math.max(0,cursor-1)),height=Math.max(150,maxY+70);
 return `<svg xmlns="http://www.w3.org/2000/svg" class="rb-tree-svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="合法红黑树折叠为 2–3–4 树"><title>把红孩子与黑父折叠为多键节点</title><g font-family="Microsoft YaHei,sans-serif" text-anchor="middle">${edges.map(([a,b])=>`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#91a59a"/>`).join('')}${placed.map(({n,x,y})=>`<rect x="${x-65}" y="${y-23}" width="130" height="46" rx="7" fill="#e8efe2" stroke="#5a8467"/><text x="${x}" y="${y+5}" font-size="17" fill="#244535">${n.keys.join(' | ')}</text><text x="${x}" y="${y+43}" font-size="11" fill="#75806f">${n.keys.length+1}-node</text>`).join('')}${!tree?'<text x="165" y="70">空树</text>':''}</g></svg>`
}
